import{_ as e,o as i,c as s,a2 as a}from"./chunks/framework.DnrXFDHb.js";const k=JSON.parse('{"title":"LegacyInferenceEngineStanley — ML 引擎层","description":"基于 RoFormerSymbolicTransformer 的 duration-note 推理引擎","frontmatter":{"title":"LegacyInferenceEngineStanley — ML 引擎层","description":"基于 RoFormerSymbolicTransformer 的 duration-note 推理引擎"},"headers":[],"relativePath":"architecture/infrastructure/inference/stanley_legacy.md","filePath":"architecture/infrastructure/inference/stanley_legacy.md","lastUpdated":1775717144000}'),n={name:"architecture/infrastructure/inference/stanley_legacy.md"};function o(l,t,r,d,h,c){return i(),s("div",null,[...t[0]||(t[0]=[a('<h1 id="legacyinferenceenginestanley-—-ml-引擎层" tabindex="-1">LegacyInferenceEngineStanley — ML 引擎层 <a class="header-anchor" href="#legacyinferenceenginestanley-—-ml-引擎层" aria-label="Permalink to &quot;LegacyInferenceEngineStanley — ML 引擎层&quot;">​</a></h1><p><strong>源文件</strong>：<code>src/streammuse/infrastructure/inference/stanley_legacy.py</code></p><p>直接操作 RoFormer 模型的推理引擎，使用 duration-note 字典和 piano-roll 张量，不依赖 Domain 层。</p><hr><h2 id="初始化" tabindex="-1">初始化 <a class="header-anchor" href="#初始化" aria-label="Permalink to &quot;初始化&quot;">​</a></h2><div class="language-python vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">class</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> LegacyInferenceEngineStanley</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    def</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> __init__</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        self,</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">        *</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        checkpoint_path: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">str</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        model_size: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">str</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        generation_length_frames: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">int</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        max_polyphony: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">int</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 4</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        model_max_seq_len_frames: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">int</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 96</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    ) -&gt; </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">None</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span></code></pre></div><p>初始化时：</p><ol><li>验证 <code>checkpoint_path</code> 存在，不存在则抛出 <code>FileNotFoundError</code></li><li>调用 <code>RoFormerSymbolicTransformer.load_from_checkpoint()</code> 加载模型</li><li>若 CUDA 可用，将模型移至 <code>&quot;cuda:0&quot;</code>，否则在 CPU 上运行</li><li>设置 <code>model.eval()</code> 模式（关闭 dropout 等训练专用层）</li><li>初始化历史记录：<code>melody_history = []</code>，<code>accompaniment_history = []</code></li></ol><h3 id="关键内部状态" tabindex="-1">关键内部状态 <a class="header-anchor" href="#关键内部状态" aria-label="Permalink to &quot;关键内部状态&quot;">​</a></h3><table tabindex="0"><thead><tr><th>属性</th><th>说明</th></tr></thead><tbody><tr><td><code>model</code></td><td><code>RoFormerSymbolicTransformer</code> 实例</td></tr><tr><td><code>model_max_seq_len_frames</code></td><td>context window 帧数（如 96）</td></tr><tr><td><code>prompt_length_ticks</code></td><td><code>model_max_seq_len_frames // 2</code>（如 48 ticks）</td></tr><tr><td><code>generation_length_frames</code></td><td>每次生成帧数（如 20）</td></tr><tr><td><code>max_polyphony</code></td><td>最大和弦大小（如 4）</td></tr><tr><td><code>melody_history</code></td><td>历史旋律 note dicts</td></tr><tr><td><code>accompaniment_history</code></td><td>历史伴奏 note dicts</td></tr><tr><td><code>injection_offset_ticks</code></td><td>注入偏移（ticks）</td></tr></tbody></table><hr><h2 id="数据格式" tabindex="-1">数据格式 <a class="header-anchor" href="#数据格式" aria-label="Permalink to &quot;数据格式&quot;">​</a></h2><h3 id="note-字典格式" tabindex="-1">Note 字典格式 <a class="header-anchor" href="#note-字典格式" aria-label="Permalink to &quot;Note 字典格式&quot;">​</a></h3><div class="language-python vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;pitch&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">60</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;tick&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">12</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;duration&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">4</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;velocity&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">80</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p><code>duration</code> 量化为 <code>DURATION_TEMPLATES</code> 中的离散值。</p><h3 id="piano-roll-张量格式" tabindex="-1">Piano-roll 张量格式 <a class="header-anchor" href="#piano-roll-张量格式" aria-label="Permalink to &quot;Piano-roll 张量格式&quot;">​</a></h3><p>形状：<code>(max_tick, max_polyphony, 3)</code>，各维含义：</p><table tabindex="0"><thead><tr><th>维度</th><th>含义</th></tr></thead><tbody><tr><td><code>[tick, slot, 0]</code></td><td>program（乐器编号，254=空位，255=填充）</td></tr><tr><td><code>[tick, slot, 1]</code></td><td>pitch（MIDI 音高 0–127）</td></tr><tr><td><code>[tick, slot, 2]</code></td><td>duration_idx（从 <code>DURATION_TEMPLATES</code> 量化的索引）</td></tr></tbody></table><p>EOS_TOKEN 和 PAD_TOKEN 为特殊占位符。</p><hr><h2 id="核心方法" tabindex="-1">核心方法 <a class="header-anchor" href="#核心方法" aria-label="Permalink to &quot;核心方法&quot;">​</a></h2><h3 id="generate-accompaniment-melody-notes-generation-start-tick-acc-notes-none-tuple" tabindex="-1"><code>generate_accompaniment(melody_notes, generation_start_tick, acc_notes=None, ...) -&gt; tuple</code> <a class="header-anchor" href="#generate-accompaniment-melody-notes-generation-start-tick-acc-notes-none-tuple" aria-label="Permalink to &quot;`generate_accompaniment(melody_notes, generation_start_tick, acc_notes=None, ...) -&gt; tuple`&quot;">​</a></h3><ol><li>将 <code>melody_notes</code> + 历史数据通过 <code>_notes_to_rolls()</code> 转为 piano-roll 张量</li><li>将张量输入 <code>model.generate()</code>（自回归生成）</li><li>通过 <code>_tensors_to_notes()</code> 将输出张量转回 note 字典</li><li>更新 <code>melody_history</code> 和 <code>accompaniment_history</code></li><li>返回 <code>(acc_notes, preprocess_start, inf_start, inf_end, post_start)</code>（4 个时间戳用于性能分析）</li></ol><h3 id="notes-to-rolls-notes-max-tick-max-polyphony-program-torch-tensor" tabindex="-1"><code>_notes_to_rolls(notes, max_tick, max_polyphony, program) -&gt; torch.Tensor</code> <a class="header-anchor" href="#notes-to-rolls-notes-max-tick-max-polyphony-program-torch-tensor" aria-label="Permalink to &quot;`_notes_to_rolls(notes, max_tick, max_polyphony, program) -&gt; torch.Tensor`&quot;">​</a></h3><p>将 note 字典列表转换为形状 <code>(max_tick, max_polyphony * 3)</code> 的张量（reshape 后）。同一 tick 内的多个音符按音高排序，超出 <code>max_polyphony</code> 的音符被丢弃。</p><h3 id="tensors-to-notes-output-tensors-generation-start-tick-list-list-dict" tabindex="-1"><code>_tensors_to_notes(output_tensors, generation_start_tick) -&gt; list[list[dict]]</code> <a class="header-anchor" href="#tensors-to-notes-output-tensors-generation-start-tick-list-list-dict" aria-label="Permalink to &quot;`_tensors_to_notes(output_tensors, generation_start_tick) -&gt; list[list[dict]]`&quot;">​</a></h3><p>将模型输出张量列表解码为 note 字典列表。跳过 EOS/PAD 标记，将 <code>pitch_duration</code> 编码拆分为 pitch（低 7 位）和 duration_idx（高位），通过 <code>DURATION_TEMPLATES</code> 还原为实际 duration。</p><h3 id="clear-history-none" tabindex="-1"><code>clear_history() -&gt; None</code> <a class="header-anchor" href="#clear-history-none" aria-label="Permalink to &quot;`clear_history() -&gt; None`&quot;">​</a></h3><p>清空 <code>melody_history</code> 和 <code>accompaniment_history</code>。</p><h3 id="set-injection-offset-offset-ticks-int-none" tabindex="-1"><code>set_injection_offset(offset_ticks: int) -&gt; None</code> <a class="header-anchor" href="#set-injection-offset-offset-ticks-int-none" aria-label="Permalink to &quot;`set_injection_offset(offset_ticks: int) -&gt; None`&quot;">​</a></h3><p>设置注入偏移，供上层注入流程（HTTP API 或编程调用）使用。</p>',31)])])}const _=e(n,[["render",o]]);export{k as __pageData,_ as default};
